/// Delay before retry number `attempt` (1-based). The documented contract:
/// the first retry waits exactly `base_delay_ms`; growth doubles and
/// saturates at `max_delay_ms`; large attempt numbers saturate at the cap
/// rather than wrapping to zero.
pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    // `attempt` is 1-based, so the first retry (attempt == 1) is the base
    // delay with no doubling yet: shift = attempt - 1.
    let shift = attempt.saturating_sub(1).min(63);
    // Saturating arithmetic keeps even base values from shifting to zero
    // (e.g. 100 << 63 == 0), which would wrap below the cap.
    let raw = config.base_delay_ms.saturating_mul(1u64 << shift);
    if raw > config.max_delay_ms {
        config.max_delay_ms
    } else {
        raw
    }
}

